  const getConfiguredThinkingType = (preset = {}) => String(preset?.thinking_type || preset?.thinkingType || preset?.glm_thinking_type || 'enabled').trim().toLowerCase() === 'disabled' ? 'disabled' : 'enabled';
  const providerModelLeaf = (model) => {
    const normalized = String(model || '').trim().replace(/^models\//i, '');
    const parts = normalized.split('/').filter(Boolean);
    return String(parts[parts.length - 1] || normalized).toLowerCase();
  };
  const isGpt56Model = model => /^gpt-5\.6(?:$|[-_.])/i.test(providerModelLeaf(model));
  const isKimiK3Model = model => /^kimi-k3(?:$|[-_.\[])/i.test(providerModelLeaf(model));
