      responseFamily: 'response_family', libraResponseMode: 'libra_response_mode', gradiaWritingMode: 'gradia_writing_mode',
      liveContextEnabled: 'live_context_enabled', liveTailMaxTurns: 'live_tail_max_turns', liveTailMaxChars: 'live_tail_max_chars',
