  const promptProfileHash = value => {
    try {
      const hasher = createTextHasher();
      hasher.update(typeof value === 'string' ? value : JSON.stringify(value ?? null));
      return hasher.digest();
    } catch (_) { return ''; }
  };

  const normalizeEasyPromptMeta = value => {
    const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    const rawConfigs = source.configs && typeof source.configs === 'object' && !Array.isArray(source.configs) ? source.configs : {};
    const configs = {};
    for (const [rawKey, rawValue] of Object.entries(rawConfigs)) {
      const key = compact(rawKey, 80);
      if (!key) continue;
      const cfg = rawValue && typeof rawValue === 'object' && !Array.isArray(rawValue) ? rawValue : {};
      const emphasisSource = cfg.emphasis && typeof cfg.emphasis === 'object' && !Array.isArray(cfg.emphasis) ? cfg.emphasis : {};
      configs[key] = {
        style: compact(cfg.style || '', 40),
        strictness: compact(cfg.strictness || '', 40),
        emphasis: {
          character: emphasisSource.character === true,
          chronology: emphasisSource.chronology === true,
          world: emphasisSource.world === true,
          narrative: emphasisSource.narrative === true
        },
        addendum: compact(cfg.addendum || '', 6000)
      };
    }
    return { version: EASY_PROMPT_CONFIG_VERSION, configs };
  };

  const normalizePromptSectionOverride = value => {
    if (typeof value === 'string') return { mode: 'append', text: compact(value, 30000) };
    const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    return {
      mode: normalizeChoice(String(source.mode || 'inherit').toLowerCase(), PROMPT_PROFILE_SECTION_MODES, 'inherit'),
      text: compact(source.text ?? source.prompt ?? source.value ?? '', 30000)
    };
  };

  const normalizeMemoryPromptProfile = (value = {}, fallbackName = '') => {
    const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    const stages = {};
    for (const stageId of MEMORY_PROMPT_PROFILE_STAGE_IDS) {
      const stageSource = source.stages?.[stageId] || source[stageId] || {};
      const sectionSource = stageSource.sections || stageSource;
      const allowed = new Set((MEMORY_PROMPT_SECTION_DEFS[stageId] || []).map(item => item.id));
      const sections = {};
      for (const [sectionId, sectionValue] of Object.entries(sectionSource || {})) {
        if (!allowed.has(sectionId)) continue;
        sections[sectionId] = normalizePromptSectionOverride(sectionValue);
      }
      stages[stageId] = { sections };
    }
    return {
      schema: MEMORY_PROMPT_PROFILE_SCHEMA,
      name: compact(source.name || fallbackName || 'Memory Profile', 120),
      version: Math.max(1, Number(source.version || 1) || 1),
      baseVersion: PROMPT_PROFILE_COMPILER_VERSION,
      easy: normalizeEasyPromptMeta(source.easy),
      stages
    };
  };

