  const normalizePromptProfileBank = (value, kind = 'memory') => {
    const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    const out = {};
    for (const [rawName, rawProfile] of Object.entries(source)) {
      const name = compact(rawName, 120);
      if (!name || name === PROMPT_PROFILE_DEFAULT_NAME) continue;
      out[name] = kind === 'planner'
        ? normalizePlannerPromptProfile(rawProfile, name)
        : kind === 'sga'
          ? normalizeSgaPromptProfile(rawProfile, name)
          : kind === 'input_writer'
            ? normalizeInputWriterPromptProfile(rawProfile, name)
            : normalizeMemoryPromptProfile(rawProfile, name);
      out[name].name = name;
    }
    return out;
  };

