        deepseek: Object.freeze({ label: 'DeepSeek Reasoner', reasoningEffort: 'none', reasoningBudgetTokens: 0, maxCompletionTokens: 64000, thinkingType: 'enabled', controls: [], hint: 'deepseek-reasoner가 자체 추론합니다. max_tokens만 적용하고 temperature는 보내지 않습니다.' }),
        kimi: Object.freeze({ label: 'Kimi', reasoningEffort: 'none', reasoningBudgetTokens: 0, maxCompletionTokens: 32000, thinkingType: 'enabled', controls: ['thinking'], hint: 'Kimi K2.6의 thinking.type을 사용합니다. reasoning_content와 최종 응답은 함께 max_tokens에 포함됩니다.' }),
        glm: Object.freeze({ label: 'GLM', reasoningEffort: 'none', reasoningBudgetTokens: 0, maxCompletionTokens: 24000, thinkingType: 'enabled', controls: ['thinking'], hint: 'Z.AI GLM의 thinking.type=enabled/disabled를 사용합니다.' }),
        ollama: Object.freeze({ label: 'Ollama native thinking', reasoningEffort: 'medium', reasoningBudgetTokens: 0, maxCompletionTokens: 20000, thinkingType: 'enabled', controls: ['thinking', 'effort'], hint: 'Ollama /api/chat의 think boolean 또는 low/medium/high/max 레벨을 사용합니다.' }),
