    const getConfiguredThinkingType = (llmConfig = {}) => String(llmConfig?.thinkingType || llmConfig?.thinking_type || llmConfig?.glmThinkingType || llmConfig?.glm_thinking_type || 'enabled').trim().toLowerCase() === 'disabled' ? 'disabled' : 'enabled';
