            CONTEXT_GROUPING_VERSION,
            normalizeProvider,
            normalizeConfig,
            normalizeDimensions,
            allowedDimensionsFor,
            validateProviderDimensions,
            validateConfig,
            profileFor,
            requestFingerprintFor,
            embedTexts,
            testConnection,
            clearQueryCache,
            getQueryCacheStats: () => ({ ...queryCacheStats, size: queryCache.size, inFlight: queryInFlight.size }),
