        await setString(cfg.embed, 'provider', 'embedding_provider');
        await setString(cfg.embed, 'url', 'embedding_url');
        await setString(cfg.embed, 'key', 'embedding_key');
        await setString(cfg.embed, 'model', 'embedding_model');
        const embedTimeout = await firstArgument('embedding_timeout_ms');
        if (embedTimeout !== undefined)
            cfg.embed.timeout = normalizeTimeoutConfig(embedTimeout, cfg.embed.timeout);
        await setString(cfg.embed, 'dimensions', 'embedding_dimensions');
        await setString(cfg.embed, 'batchSize', 'embedding_batch_size');
        await setNumber(cfg.embed, 'maxRetries', cfg.embed.maxRetries, 'embedding_max_retries');
        await setString(cfg.embed, 'inputMode', 'embedding_input_mode');
        await setString(cfg.embed, 'queryTask', 'embedding_query_task');
        await setString(cfg.embed, 'documentTask', 'embedding_document_task');
        await setString(cfg.embed, 'queryPrefix', 'embedding_query_prefix');
        await setString(cfg.embed, 'documentPrefix', 'embedding_document_prefix');
        await setBoolean(cfg.embed, 'normalizeVectors', cfg.embed.normalizeVectors, 'embedding_normalize_vectors');
        await setString(cfg.embed, 'customRequestTemplate', 'embedding_custom_request_template');
        await setString(cfg.embed, 'customResponsePath', 'embedding_custom_response_path');
        await setString(cfg.embed, 'customErrorPath', 'embedding_custom_error_path');
        await setString(cfg.embed, 'customMethod', 'embedding_custom_method');
        const presets = await firstArgument('llm_presets_json', 'model_presets_json', 'provider_presets_json');
        if (presets !== undefined)
            cfg.llmPresets = parseJsonConfig(presets, cfg.llmPresets);
        const routing = await firstArgument('llm_routing_json');
        if (routing !== undefined)
            cfg.llmRouting = normalizeLLMRouteMap(parseJsonConfig(routing, cfg.llmRouting));
        const defaultPreset = await firstArgument('llm_default_preset', 'default_preset');
        if (defaultPreset !== undefined)
            cfg.llmDefaultPreset = normalizeLLMPresetName(defaultPreset) || 'primary';
        cfg.llm.timeout = normalizeTimeoutConfig(cfg.llm.timeout, 120000);
        cfg.auxLlm.timeout = normalizeTimeoutConfig(cfg.auxLlm.timeout, 90000);
        cfg.embed.timeout = normalizeTimeoutConfig(cfg.embed.timeout, 120000);
        cfg.llm.requestFormat = normalizeLLMRequestFormat(cfg.llm.requestFormat);
        cfg.auxLlm.requestFormat = normalizeLLMRequestFormat(cfg.auxLlm.requestFormat);
