    const SGA_RUNTIME_ALGORITHM_VERSION = 'libra.sga_runtime_algorithm.v4';
    const SGA_DRAFT_CHECKPOINT_STORE_SCHEMA = 'libra.sga_draft_checkpoint_store.v1';
