        ...asArray(artifact.chronology), ...asArray(artifact.characters), ...asArray(artifact.relationships),
        ...asArray(artifact.world), ...asArray(artifact.openThreads), ...asArray(artifact.uncertainties),
        ...asArray(artifact.state?.characters), ...asArray(artifact.state?.relationships), ...asArray(artifact.state?.world)
