      const defaultReasoningTokens = Math.min(60000, Math.max(16000, maxPhysicalCalls * 6000));
      const defaultTotalTokens = Math.min(380000, Math.ceil((defaultInputTokens + defaultOutputTokens) * 1.12));
      const maxInputTokens = clampInt(settings?.sgaMaxInputTokens, 20000, 1000000, defaultInputTokens);
      const maxOutputTokens = clampInt(settings?.sgaMaxOutputTokens, 8000, 300000, defaultOutputTokens);
      const maxReasoningTokens = clampInt(settings?.sgaMaxReasoningTokens, 0, 200000, defaultReasoningTokens);
      const maxTotalTokens = clampInt(settings?.sgaMaxTotalTokens, 30000, 1200000, Math.max(maxInputTokens + maxOutputTokens, defaultTotalTokens));
      const controller = typeof AbortController === 'function' ? new AbortController() : null;
