      row.finishedAt = Date.now();
      row.elapsedMs = row.finishedAt - Number(row.startedAt || row.finishedAt);
      row.ok = !error && result?.ok === true;
      row.reason = compact(error?.message || result?.reason || '', 700);
      row.finishReason = string(result?.finishReason || '');
