      if (guard.usage.outputTokens > Number(guard.maxOutputTokens || Number.POSITIVE_INFINITY)) breaches.push('output');
      if (guard.usage.reasoningTokens > Number(guard.maxReasoningTokens || Number.POSITIVE_INFINITY)) breaches.push('reasoning');
