        maxWallMs: Number(guard?.maxWallMs || 0), maxPhysicalCalls: Number(guard?.maxPhysicalCalls || 0),
        maxInputTokens: Number(guard?.maxInputTokens || 0), maxOutputTokens: Number(guard?.maxOutputTokens || 0),
