          schema: SGA_SHADOW_SCHEMA,
          allowed: ['schema','ok','continuity_locks','user_agency_locks','do_not_reveal','scene_design','draft'],
          required: ['schema','ok','continuity_locks','user_agency_locks','do_not_reveal','scene_design','draft']
