        if (!isPlainObject(edit)) return 'edit_not_object';
        if (Object.keys(edit).some(key => !['operation','target','expected_hash','content','reason'].includes(key))) return 'edit_unknown_field';
        const operation = normalizeAidePatchOperation(edit.operation);
        const target = string(edit.target || '');
        const expectedHash = string(edit.expected_hash || '');
        const content = string(edit.content ?? '');
        if (!operation) return 'edit_operation_invalid';
        if (!/^p\d{3,}$/i.test(target)) return 'edit_target_invalid';
        if (!/^[0-9a-f]{8}$/i.test(expectedHash)) return 'edit_hash_invalid';
        if (operation !== 'delete' && !content) return 'edit_content_missing';
        if (content.length > SGA_PATCH_CONTENT_MAX_CHARS) return 'edit_content_too_large';
