        const operation = normalizeAidePatchOperation(edit.operation);
        const target = compact(edit.target || '', 32);
        const expectedHash = compact(edit.expected_hash || '', 24);
        const content = text(edit.content ?? '').trim();
        if (!operation || !/^p\d{3,}$/i.test(target) || !/^[0-9a-f]{8}$/i.test(expectedHash)) return null;
        if (operation !== 'delete' && !content) return null;
