      if (canonicalJobActive(state.canonicalJob) && string(state.canonicalJob?.jobId || '') !== string(jobId || '')) throw new Error('canonical_job_busy');
      const job = await loadCanonicalJob(context.scope, jobId);
      if (!job || !['awaiting_choice', 'adopting'].includes(job.state)) throw new Error('canonical_job_not_awaiting_choice');
      const normalizedDecision = string(decision || '').toLowerCase();
      if (['later', 'defer'].includes(normalizedDecision)) return await updateCanonicalJob(context.scope, { message: '결정을 보류했습니다. 실행 기록에서 비교창을 다시 열 수 있습니다.' });
