    async debugBuildAriadneReferenceContext(startTurn = 0) {
      const context = await LibraMemoryCore.resolveContext();
      const pairs = LibraMemoryCore.buildPairs(context.chat, context?.scope?.scopeKey || '');
      const start = Number(startTurn || 0) > 0 ? Number(startTurn) : Math.max(1, Math.floor((Math.max(1, pairs.length) - 1) / LibraMemoryCore.BATCH_SIZE) * LibraMemoryCore.BATCH_SIZE + 1);
      const batch = pairs.slice(start - 1, start - 1 + LibraMemoryCore.BATCH_SIZE);
      if (batch.length !== LibraMemoryCore.BATCH_SIZE) throw new Error('완성된 5턴 배치를 찾을 수 없습니다.');
      const result = await LibraMemoryCore.buildAriadneReferenceContext(batch);
      return safeClone({ meta: result.meta, block: result.block, packet: result.packet });
    },
    async debugRerankMemoryLore(stageName = 'ariadne', startTurn = 0) {
      const stage = LibraMemoryCore.STAGE_ORDER.includes(stageName) ? stageName : 'ariadne';
      const context = await LibraMemoryCore.resolveContext();
      const pairs = LibraMemoryCore.buildPairs(context.chat, context?.scope?.scopeKey || '');
      const start = Number(startTurn || 0) > 0 ? Number(startTurn) : Math.max(1, Math.floor((Math.max(1, pairs.length) - 1) / LibraMemoryCore.BATCH_SIZE) * LibraMemoryCore.BATCH_SIZE + 1);
      const batch = pairs.slice(start - 1, start - 1 + LibraMemoryCore.BATCH_SIZE);
      if (batch.length !== LibraMemoryCore.BATCH_SIZE) throw new Error('완성된 5턴 배치를 찾을 수 없습니다.');
      if (stage === 'ariadne') {
        const result = await LibraMemoryCore.buildAriadneReferenceContext(batch);
        return safeClone({ stage, meta: result.meta?.loreRerank || null });
      }
      const memories = await LibraMemoryCore.getSnapshot?.()?.memories;
      const draft = '';
      const result = await LibraMemoryCore.buildItoLoreReferenceContext(stage, batch, draft);
      return safeClone({ stage, meta: result.meta, block: result.block });
    },
